Think: For each path listed in temp_checks/matches_raw.txt, check whether it is a regular file, directory, symlink, or other, and append "path:type" lines to temp_checks/matches_checked.txt using a single awk command that runs test on each path.

Act: bash

```bash
awk '{
 cmd = "test -f \"" $0 "\""
 if (system(cmd) == 0) { print $0":regular file" }
 else {
  cmd2 = "test -d \"" $0 "\""
  if (system(cmd2) == 0) { print $0":directory" }
  else {
    cmd3 = "test -L \"" $0 "\""
    if (system(cmd3) == 0) { print $0":symlink" }
    else { print $0":other" }
  }
 }
}' temp_checks/matches_raw.txt >> temp_checks/matches_checked.txt
